sp_widget.client_script:
api.controller = function($location) {

  var c = this;


  // =========================================================
  // INITIALIZATION
  // =========================================================

  c.$onInit = function() {

    // Dashboard data is loaded by the Server Script.
    console.log('Patient Dashboard loaded');

  };


  // =========================================================
  // REFRESH DASHBOARD
  // =========================================================

  c.refresh = function() {

    // Reload the latest appointment/report information
    // from the ServiceNow server.
    //
    // Example:
    //
    // Pending → Admin approves → Refresh
    //                    ↓
    //              Tracker updates
    //
    c.server.update();

  };


  // =========================================================
  // STATUS LABEL
  // =========================================================

  c.getStatusLabel = function(status) {

    var labels = {

      pending: 'Pending',

      confirmed: 'Confirmed',

      completed: 'Completed',

      cancelled: 'Cancelled',

      rejected: 'Rejected'

    };

    return labels[status] || status || 'Unknown';

  };


  // =========================================================
  // STATUS CSS CLASS
  // =========================================================

  c.getStatusClass = function(status) {

    var classes = {

      pending: 'status-pending',

      confirmed: 'status-confirmed',

      completed: 'status-completed',

      cancelled: 'status-cancelled',

      rejected: 'status-rejected'

    };

    return classes[status] || 'status-pending';

  };


  // =========================================================
  // APPROVAL LABEL
  // =========================================================

  c.getApprovalLabel = function(status) {

    var labels = {

      requested: 'Approval Requested',

      approved: 'Approved',

      rejected: 'Rejected'

    };

    return labels[status] || status || '';

  };


  // =========================================================
  // 4-STAGE APPOINTMENT TRACKING
  // =========================================================
  //
  // Our four stages are:
  //
  // 1. Pending
  // 2. Approved
  // 3. Completed
  // 4. Report Available
  //
  // The current stage is determined from REAL
  // ServiceNow appointment/report data.
  //
  // =========================================================


  c.getTrackingStepClass = function(step, appointment) {

    if (!appointment) {

      return 'tracking-upcoming';

    }


    // -------------------------------------------------------
    // Read the actual values from the appointment.
    // -------------------------------------------------------

    var status =
      (appointment.status || '').toLowerCase();

    var approvalStatus =
      (appointment.approval_status || '').toLowerCase();


    // -------------------------------------------------------
    // REPORT AVAILABILITY
    // -------------------------------------------------------
    //
    // Server Script sets has_report = true when a Report
    // record exists for this appointment.
    //
    // -------------------------------------------------------

    var hasReport =
      appointment.has_report === true;


    // -------------------------------------------------------
    // CANCELLED / REJECTED
    // -------------------------------------------------------

    if (
      status === 'cancelled' ||
      status === 'rejected' ||
      approvalStatus === 'rejected'
    ) {

      return 'tracking-cancelled';

    }


    // =======================================================
    // STAGE 1 — PENDING
    // =======================================================

    if (step === 'pending') {

      // If approval is still requested,
      // Pending is the current stage.
      if (approvalStatus === 'requested') {

        return 'tracking-current';

      }

      // Once approved, Pending is completed.
      if (approvalStatus === 'approved') {

        return 'tracking-completed';

      }

      // Default
      return 'tracking-upcoming';

    }


    // =======================================================
    // STAGE 2 — APPROVED
    // =======================================================

    if (step === 'approved') {

      // Approval has happened.
      if (approvalStatus === 'approved') {

        // If appointment is completed or report exists,
        // Approved is already completed.
        if (
          status === 'completed' ||
          hasReport
        ) {

          return 'tracking-completed';

        }

        // Otherwise Approved is the current stage.
        return 'tracking-current';

      }

      // Approval has not happened yet.
      return 'tracking-upcoming';

    }


    // =======================================================
    // STAGE 3 — COMPLETED
    // =======================================================

    if (step === 'completed') {

      if (status === 'completed') {

        // If report exists, Completed is already finished.
        if (hasReport) {

          return 'tracking-completed';

        }

        // Appointment is completed but report is not
        // available yet.
        return 'tracking-current';

      }

      return 'tracking-upcoming';

    }


    // =======================================================
    // STAGE 4 — REPORT AVAILABLE
    // =======================================================

    if (step === 'report') {

      if (hasReport) {

        return 'tracking-current';

      }

      return 'tracking-upcoming';

    }


    return 'tracking-upcoming';

  };


  // =========================================================
  // TRACKING DESCRIPTION
  // =========================================================

  c.getTrackingDescription = function(step, appointment) {

    if (!appointment) {

      return '';

    }


    var approvalStatus =
      (appointment.approval_status || '').toLowerCase();

    var status =
      (appointment.status || '').toLowerCase();

    var hasReport =
      appointment.has_report === true;


    // -------------------------------------------------------
    // PENDING
    // -------------------------------------------------------

    if (step === 'pending') {

      if (approvalStatus === 'requested') {

        return 'Your booking is waiting for administrator approval.';

      }

      return 'Your booking request was submitted.';

    }


    // -------------------------------------------------------
    // APPROVED
    // -------------------------------------------------------

    if (step === 'approved') {

      if (approvalStatus === 'approved') {

        return 'Your appointment has been approved.';

      }

      return 'Your appointment is waiting for approval.';

    }


    // -------------------------------------------------------
    // COMPLETED
    // -------------------------------------------------------

    if (step === 'completed') {

      if (status === 'completed' && !hasReport) {

        return 'Your test is completed. Your report is being prepared.';

      }

      if (hasReport) {

        return 'Your diagnostic test has been completed.';

      }

      return 'Your diagnostic test will be completed after your appointment.';

    }


    // -------------------------------------------------------
    // REPORT
    // -------------------------------------------------------

    if (step === 'report') {

      if (hasReport) {

        return 'Your diagnostic report is ready to view.';

      }

      return 'Your report will appear here once it is generated.';

    }


    return '';

  };


  // =========================================================
  // NAVIGATION
  // =========================================================

  // Open Test Catalog
  c.bookTest = function() {

    $location.search({

      id: 'test_catalog'

    });

  };


  // Open My Appointments
  c.goBookings = function() {

    $location.search({

      id: 'my_appointments'

    });

  };


  // Open Lab Reports
  c.goReports = function() {

    $location.search({

      id: 'lab_reports'

    });

  };

};

sp_widget.css:
/* =========================================================
   PATIENT DASHBOARD
   All CSS is scoped under .patient-dashboard
   so existing portal widgets are not affected.
   ========================================================= */

.patient-dashboard {
  --primary: #0a2463;
  --accent: #00b4d8;
  --success: #10b981;
  --warning: #f59e0b;
  --danger: #ef4444;
  --purple: #8b5cf6;

  --gray-50: #f8fafc;
  --gray-100: #f1f5f9;
  --gray-200: #e2e8f0;
  --gray-500: #64748b;
  --gray-700: #334155;
  --gray-900: #0f172a;

  font-family: "Segoe UI", system-ui, sans-serif;
  background: var(--gray-50);
  min-height: 100vh;
  padding-bottom: 50px;
}


/* ================= HEADER ================= */

.dashboard-header {
  background: linear-gradient(135deg, #0a2463, #1e5c91);
  color: white;

  padding: 38px 40px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  border-radius: 0 0 28px 28px;
}

.welcome-tag {
  display: inline-block;

  font-size: 12px;
  font-weight: 700;

  background: rgba(255,255,255,0.15);
  padding: 7px 13px;
  border-radius: 20px;

  margin-bottom: 12px;
}

.dashboard-header h1 {
  margin: 0 0 8px;
  font-size: 30px;
  font-weight: 800;
}

.dashboard-header p {
  margin: 0;
  opacity: 0.85;
}


/* ================= REFRESH ================= */

.refresh-btn {
  border: 1px solid rgba(255,255,255,0.35);
  background: rgba(255,255,255,0.12);
  color: white;

  padding: 10px 16px;
  border-radius: 9px;

  cursor: pointer;
}

.refresh-btn:hover {
  background: rgba(255,255,255,0.2);
}


/* ================= MAIN GRID ================= */

.top-grid {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 20px;

  padding: 25px 35px 0;
}


/* ================= PROFILE ================= */

.profile-card {
  background: white;
  border: 1px solid var(--gray-200);

  border-radius: 16px;
  padding: 25px;

  display: flex;
  align-items: center;
  gap: 20px;

  box-shadow: 0 3px 12px rgba(0,0,0,0.05);
}

.profile-avatar {
  width: 70px;
  height: 70px;

  border-radius: 50%;

  background: #e0f2fe;
  color: var(--primary);

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 28px;
}

.profile-info h2 {
  margin: 0 0 10px;
  color: var(--gray-900);
  font-size: 20px;
}

.profile-info p {
  margin: 6px 0;
  color: var(--gray-500);
  font-size: 13px;
}

.profile-info i {
  width: 18px;
}


/* ================= STATISTICS ================= */

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.stat-card {
  background: white;
  border: 1px solid var(--gray-200);

  border-radius: 14px;
  padding: 18px;

  display: flex;
  align-items: center;
  gap: 15px;

  box-shadow: 0 3px 12px rgba(0,0,0,0.04);
}

.stat-card strong {
  display: block;

  font-size: 25px;
  color: var(--gray-900);
}

.stat-card span {
  display: block;

  font-size: 12px;
  color: var(--gray-500);

  margin-top: 3px;
}

.stat-icon {
  width: 45px;
  height: 45px;

  border-radius: 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 19px;
}

.stat-icon.blue {
  background: #dbeafe;
  color: #2563eb;
}

.stat-icon.orange {
  background: #fef3c7;
  color: #d97706;
}

.stat-icon.green {
  background: #dcfce7;
  color: #16a34a;
}

.stat-icon.purple {
  background: #ede9fe;
  color: #7c3aed;
}


/* ================= SECTION HEADER ================= */

.section-header {
  padding: 30px 35px 15px;

  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-header h2 {
  margin: 0 0 5px;

  font-size: 21px;
  color: var(--gray-900);
}

.section-header p {
  margin: 0;

  font-size: 13px;
  color: var(--gray-500);
}

.link-btn {
  border: none;
  background: transparent;

  color: var(--accent);

  font-weight: 700;
  cursor: pointer;
}


/* ================= UPCOMING APPOINTMENT ================= */

.upcoming-card {
  margin: 0 35px;

  background: white;
  border: 1px solid var(--gray-200);

  border-radius: 16px;
  padding: 22px;

  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  align-items: center;
  gap: 20px;

  box-shadow: 0 3px 12px rgba(0,0,0,0.05);
}

.upcoming-test {
  display: flex;
  align-items: center;
  gap: 15px;
}

.test-icon {
  width: 50px;
  height: 50px;

  border-radius: 12px;

  background: #e0f2fe;
  color: #0284c7;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 21px;
}

.upcoming-test h3 {
  margin: 0 0 5px;
  font-size: 16px;
  color: var(--gray-900);
}

.appointment-number {
  font-size: 11px;
  color: var(--gray-500);
}

.appointment-detail {
  display: flex;
  align-items: center;
  gap: 10px;
}

.appointment-detail > i {
  color: var(--accent);
  font-size: 18px;
}

.appointment-detail span {
  display: block;
  color: var(--gray-500);
  font-size: 11px;
}

.appointment-detail strong {
  display: block;
  color: var(--gray-900);
  font-size: 13px;
  margin-top: 3px;
}


/* ================= STATUS ================= */

.status-pill,
.approval-pill {
  display: inline-block;

  padding: 6px 10px;
  border-radius: 20px;

  font-size: 11px;
  font-weight: 700;

  margin-right: 5px;
}

.status-pending {
  background: #fef3c7;
  color: #92400e;
}

.status-confirmed {
  background: #dcfce7;
  color: #166534;
}

.status-completed {
  background: #dbeafe;
  color: #1d4ed8;
}

.status-cancelled,
.status-rejected {
  background: #fee2e2;
  color: #b91c1c;
}

.approval-pill {
  background: #f1f5f9;
  color: #475569;
}


/* ================= EMPTY ================= */

.empty-card {
  margin: 0 35px;

  background: white;

  border: 1px dashed var(--gray-200);
  border-radius: 16px;

  padding: 35px;
  text-align: center;
}

.empty-icon {
  font-size: 30px;
  color: #94a3b8;
  margin-bottom: 10px;
}

.empty-card h3 {
  margin: 5px 0;
  color: var(--gray-900);
}

.empty-card p {
  color: var(--gray-500);
  font-size: 13px;
}


/* ================= BUTTON ================= */

.primary-btn {
  background: var(--primary);
  color: white;

  border: none;
  border-radius: 8px;

  padding: 10px 18px;

  font-weight: 700;
  cursor: pointer;
}


/* ================= REPORTS ================= */

.reports-grid {
  margin: 0 35px;

  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.report-card {
  background: white;

  border: 1px solid var(--gray-200);
  border-radius: 14px;

  padding: 18px;

  display: flex;
  align-items: center;
  gap: 15px;
}

.report-icon {
  width: 45px;
  height: 45px;

  border-radius: 10px;

  background: #ede9fe;
  color: #7c3aed;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 18px;
}

.report-info {
  flex: 1;
}

.report-info h3 {
  margin: 0 0 4px;

  font-size: 14px;
  color: var(--gray-900);
}

.report-info span {
  display: block;

  font-size: 11px;
  color: var(--gray-500);
}

.report-info small {
  display: block;

  margin-top: 5px;

  color: var(--gray-500);
  font-size: 11px;
}

.report-status {
  background: #dcfce7;
  color: #166534;

  padding: 5px 9px;

  border-radius: 15px;

  font-size: 10px;
  font-weight: 700;
}


/* ================= QUICK ACTIONS ================= */

.quick-actions {
  margin: 30px 35px 0;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
}

.quick-actions button {
  background: white;

  border: 1px solid var(--gray-200);
  border-radius: 12px;

  padding: 17px;

  color: var(--gray-700);

  cursor: pointer;

  font-weight: 600;
}

.quick-actions i {
  color: var(--accent);
  margin-right: 8px;
}


/* ================= ERROR ================= */

.error-box {
  margin: 20px 35px 0;

  padding: 12px 15px;

  border-radius: 9px;

  background: #fee2e2;
  color: #991b1b;

  font-size: 13px;
}


/* ================= RESPONSIVE ================= */

@media (max-width: 900px) {

  .top-grid {
    grid-template-columns: 1fr;
  }

  .upcoming-card {
    grid-template-columns: 1fr;
  }

  .reports-grid {
    grid-template-columns: 1fr;
  }

  .quick-actions {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 600px) {

  .dashboard-header {
    padding: 25px 20px;

    flex-direction: column;
    align-items: flex-start;
  }

  .top-grid,
  .section-header,
  .upcoming-card,
  .reports-grid,
  .quick-actions {
    margin-left: 15px;
    margin-right: 15px;
  }

  .top-grid {
    padding-left: 0;
    padding-right: 0;
  }

  .section-header {
    padding-left: 0;
    padding-right: 0;
  }

}
/* =========================================================
   APPOINTMENT TRACKING
   4-STAGE HORIZONTAL PROGRESS TRACKER
   ========================================================= */

.tracking-section {
  margin-top: 5px;
}


/* ================= TRACKING CARD ================= */

.tracking-card {
  margin: 0 35px;

  background: white;

  border: 1px solid var(--gray-200);

  border-radius: 16px;

  padding: 25px;

  box-shadow: 0 3px 12px rgba(0,0,0,0.05);
}


/* ================= TRACKING HEADER ================= */

.tracking-header {
  display: flex;

  justify-content: space-between;

  align-items: center;

  margin-bottom: 28px;

  padding-bottom: 18px;

  border-bottom: 1px solid var(--gray-200);
}

.tracking-header h3 {
  margin: 0 0 5px;

  color: var(--gray-900);

  font-size: 17px;

  font-weight: 700;
}


/* ================= HORIZONTAL TIMELINE ================= */

.tracking-timeline {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  position: relative;

  gap: 0;

  padding-top: 10px;
}


/* ================= CONNECTING LINE ================= */

.tracking-timeline::before {
  content: "";

  position: absolute;

  top: 32px;

  left: 12.5%;

  right: 12.5%;

  height: 3px;

  background: var(--gray-200);

  z-index: 0;
}


/* ================= TRACKING STEP ================= */

.tracking-step {
  position: relative;

  z-index: 1;

  display: flex;

  flex-direction: column;

  align-items: center;

  text-align: center;

  padding: 0 12px;

  min-width: 0;
}


/* ================= TRACKING ICON ================= */

.tracking-icon {
  width: 46px;

  height: 46px;

  border-radius: 50%;

  background: white;

  border: 3px solid var(--gray-200);

  color: var(--gray-500);

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 17px;

  margin-bottom: 10px;

  transition: all 0.25s ease;
}


/* ================= STEP TITLE ================= */

.tracking-step strong {
  font-size: 13px;

  color: var(--gray-500);

  margin-bottom: 5px;
}


/* ================= STEP DESCRIPTION ================= */

.tracking-step span {
  font-size: 10px;

  line-height: 1.4;

  color: var(--gray-500);

  max-width: 150px;
}


/* =========================================================
   COMPLETED STEP
   ========================================================= */

.tracking-step.tracking-completed
.tracking-icon {

  background: var(--success);

  border-color: var(--success);

  color: white;

}


.tracking-step.tracking-completed strong {

  color: var(--success);

}


/* =========================================================
   CURRENT STEP
   ========================================================= */

.tracking-step.tracking-current
.tracking-icon {

  background: var(--primary);

  border-color: var(--primary);

  color: white;

  box-shadow:
    0 0 0 5px rgba(10,36,99,0.10);

}


.tracking-step.tracking-current strong {

  color: var(--primary);

  font-weight: 800;

}


/* =========================================================
   CANCELLED / REJECTED
   ========================================================= */

.tracking-step.tracking-cancelled
.tracking-icon {

  background: var(--danger);

  border-color: var(--danger);

  color: white;

}


.tracking-step.tracking-cancelled strong {

  color: var(--danger);

}


/* =========================================================
   UPCOMING STEP
   ========================================================= */

.tracking-step.tracking-upcoming
.tracking-icon {

  background: white;

  border-color: var(--gray-200);

  color: var(--gray-500);

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

  .tracking-card {
    margin-left: 20px;
    margin-right: 20px;
  }

  .tracking-step {
    padding: 0 6px;
  }

  .tracking-step span {
    max-width: 120px;
  }

}


@media (max-width: 600px) {

  .tracking-card {
    margin-left: 15px;
    margin-right: 15px;

    padding: 20px 10px;
  }

  .tracking-timeline {
    grid-template-columns: 1fr;

    gap: 20px;

    padding-top: 0;
  }


  /* Vertical line on mobile */
  .tracking-timeline::before {

    top: 23px;

    bottom: 23px;

    left: 50%;

    right: auto;

    width: 3px;

    height: auto;

  }


  .tracking-step {

    display: grid;

    grid-template-columns: 46px 1fr;

    column-gap: 15px;

    text-align: left;

    align-items: center;

  }


  .tracking-icon {

    grid-row: span 2;

    margin-bottom: 0;

  }


  .tracking-step strong {

    margin-bottom: 2px;

  }


  .tracking-step span {

    max-width: none;

  }

}

sp_widget.script:
(function() {

    // =========================================================
    // INITIAL DATA OBJECT
    // =========================================================

    data.error = '';

    data.currentUser = {
        first_name: '',
        last_name: '',
        full_name: '',
        email: ''
    };

    data.patient = {
        sys_id: '',
        first_name: '',
        last_name: '',
        full_name: '',
        email: '',
        phone_number: '',
        address: ''
    };

    data.stats = {
        total: 0,
        pending: 0,
        completed: 0,
        reports: 0
    };

    data.upcoming = null;

    data.recentReports = [];


    try {

        // =======================================================
        // STEP 1 — GET LOGGED-IN USER
        // =======================================================

        var userID = gs.getUserID();
        var userEmail = gs.getUser().getEmail() || '';

        if (!userID) {
            data.error = 'Unable to identify the logged-in user.';
            return;
        }


        // Get basic information from sys_user.
        var userGr = new GlideRecord('sys_user');

        if (userGr.get(userID)) {

            data.currentUser.first_name =
                userGr.getValue('first_name') || '';

            data.currentUser.last_name =
                userGr.getValue('last_name') || '';

            data.currentUser.full_name =
                userGr.getDisplayValue('name') || '';

            data.currentUser.email =
                userGr.getValue('email') || userEmail;
        }


        // =======================================================
        // STEP 2 — FIND PATIENT RECORD
        // =======================================================

        var patientGr = new GlideRecord(
            'x_2056616_medica_0_patient_table'
        );

        var patientFound = false;


        // First preference:
        // Find Patient linked directly to the logged-in sys_user.
        patientGr.addQuery('user', userID);
        patientGr.setLimit(1);
        patientGr.query();

        if (patientGr.next()) {
            patientFound = true;
        }


        // If user reference did not find anything,
        // try matching Patient by email.
        if (!patientFound && userEmail) {

            patientGr = new GlideRecord(
                'x_2056616_medica_0_patient_table'
            );

            patientGr.addQuery('email', userEmail);
            patientGr.setLimit(1);
            patientGr.query();

            if (patientGr.next()) {
                patientFound = true;
            }

        }


        // =======================================================
        // STEP 3 — BUILD PATIENT PROFILE
        // =======================================================

        var patientSysId = '';

        if (patientFound) {

            patientSysId = patientGr.getUniqueValue();

            var firstName =
                patientGr.getValue('first_name') || '';

            var lastName =
                patientGr.getValue('last_name') || '';

            data.patient.sys_id = patientSysId;

            data.patient.first_name = firstName;

            data.patient.last_name = lastName;

            data.patient.full_name =
                (firstName + ' ' + lastName).trim();

            data.patient.email =
                patientGr.getValue('email') || '';

            data.patient.phone_number =
                patientGr.getValue('phone_number') || '';

            data.patient.address =
                patientGr.getValue('address') || '';

        }


        // =======================================================
        // STEP 4 — GET APPOINTMENTS
        // =======================================================

        if (!patientSysId) {

            // Patient does not exist yet.
            // Dashboard can still show the user profile,
            // but there will be no appointment/report data.
            return;

        }


        var appointmentGr = new GlideRecord(
            'x_2056616_medica_0_appointment_table'
        );

        appointmentGr.addQuery('patient', patientSysId);

        appointmentGr.orderByDesc('scheduled_date');

        appointmentGr.query();


        // Current date/time.
        var now = new GlideDateTime();


        while (appointmentGr.next()) {

            // -----------------------------------------------
            // BASIC APPOINTMENT INFORMATION
            // -----------------------------------------------

            var appointmentNumber =
                appointmentGr.getValue('appointment_number') || '';

            var status =
                appointmentGr.getValue('status') || '';

            var approvalStatus =
                appointmentGr.getValue('approval_status') || '';

            var scheduledRaw =
                appointmentGr.getValue('scheduled_date') || '';

            var slotTime =
                appointmentGr.getValue('slot_time') || '';


            // -----------------------------------------------
            // COUNT APPOINTMENTS
            // -----------------------------------------------

            data.stats.total++;


            if (status == 'pending') {
                data.stats.pending++;
            }


            if (status == 'completed') {
                data.stats.completed++;
            }


            // -----------------------------------------------
            // GET TEST NAME
            // -----------------------------------------------

            var testName = '';

            var testSysId =
                appointmentGr.getValue('test') || '';


            if (testSysId) {

                var testGr = new GlideRecord(
                    'x_2056616_medica_0_diagnostic_test'
                );

                if (testGr.get(testSysId)) {

                    testName =
                        testGr.getValue('test_name') || '';

                }

            }


            // -----------------------------------------------
            // FORMAT DATE
            // -----------------------------------------------

            var scheduledDisplay = '';

            if (scheduledRaw) {

                try {

                    var scheduledGdt =
                        new GlideDateTime(scheduledRaw);

                    scheduledDisplay =
                        scheduledGdt.getLocalDate().getValue();

                } catch (dateError) {

                    scheduledDisplay =
                        scheduledRaw.split(' ')[0] || scheduledRaw;

                }

            }


            // -----------------------------------------------
            // FIND UPCOMING APPOINTMENT
            // -----------------------------------------------

            // Only consider appointments that are not cancelled
            // or rejected.

            if (
                scheduledRaw &&
                status != 'cancelled' &&
                status != 'rejected'
            ) {

                try {

                    var appointmentDate =
                        new GlideDateTime(scheduledRaw);

                    // If appointment is in the future,
                    // use it as the upcoming appointment.
                    if (appointmentDate.getNumericValue() >= now.getNumericValue()) {

                        if (!data.upcoming) {

                            data.upcoming = {

                                // Unique appointment record ID.
                                // We use this to connect the appointment
                                // with its corresponding report.
                                appointment_sys_id: appointmentGr.getUniqueValue(),

                                appointment_number: appointmentNumber,

                                test_name: testName || 'Diagnostic Test',

                                status: status,

                                approval_status: approvalStatus,

                                scheduled_date: scheduledRaw,

                                scheduled_date_display: scheduledDisplay,

                                slot_time: slotTime,

                                // Initially assume the report is not available.
                                // We will update this after checking the Report table.
                                has_report: false

                            };

                        }

                    }

                } catch (upcomingError) {

                    // Ignore date parsing errors.
                }

            }

        }


        // =======================================================
        // STEP 5 — GET PATIENT REPORTS
        // =======================================================

        var reportGr = new GlideRecord(
            'x_2056616_medica_0_report_table'
        );

        reportGr.addQuery('patient', patientSysId);

        // Latest reports first
        reportGr.orderByDesc('sys_created_on');

        reportGr.query();


        // Count all reports separately
        var reportCount = 0;


        while (reportGr.next()) {

            // Count every report
            reportCount++;


            // Only display the latest 4 reports
            if (data.recentReports.length >= 4) {
                continue;
            }


            var reportNumber =
                reportGr.getValue('report_number') || '';

            var reportStatus =
                reportGr.getValue('status') || '';


            // -----------------------------------------------
            // REPORT DATE
            // -----------------------------------------------

            var reportDateRaw =
                reportGr.getValue('report_date') || '';

            var reportDateDisplay = '';

            if (reportDateRaw) {

                try {

                    var reportDate =
                        new GlideDateTime(reportDateRaw);

                    reportDateDisplay =
                        reportDate.getLocalDate().getValue();

                } catch (reportDateError) {

                    reportDateDisplay =
                        reportDateRaw.split(' ')[0] || reportDateRaw;

                }

            }


            // -----------------------------------------------
            // GET TEST NAME THROUGH APPOINTMENT
            // -----------------------------------------------

            var reportTestName = '';

            var reportAppointment =
                reportGr.getValue('appointment') || '';
            // =======================================================
            // CHECK WHETHER THIS REPORT BELONGS TO THE UPCOMING
            // APPOINTMENT
            // =======================================================

            if (
                data.upcoming &&
                reportAppointment === data.upcoming.appointment_sys_id
            ) {

                // A report record exists for the appointment.
                // Therefore the final tracking stage is available.
                data.upcoming.has_report = true;

            }


            if (reportAppointment) {

                var reportApptGr = new GlideRecord(
                    'x_2056616_medica_0_appointment_table'
                );

                if (reportApptGr.get(reportAppointment)) {

                    var reportTest =
                        reportApptGr.getValue('test') || '';


                    if (reportTest) {

                        var reportTestGr = new GlideRecord(
                            'x_2056616_medica_0_diagnostic_test'
                        );

                        if (reportTestGr.get(reportTest)) {

                            reportTestName =
                                reportTestGr.getValue('test_name') || '';

                        }

                    }

                }

            }


            // -----------------------------------------------
            // SEND REPORT DATA TO CLIENT
            // -----------------------------------------------

            data.recentReports.push({

                report_number: reportNumber,

                test_name: reportTestName || 'Diagnostic Report',

                status: reportStatus || 'Ready',

                report_date_display: reportDateDisplay || 'N/A'

            });

        }


        // -------------------------------------------------------
        // TOTAL REPORT COUNT
        // -------------------------------------------------------

        data.stats.reports = reportCount;


    } catch (e) {

        // =====================================================
        // ERROR HANDLING
        // =====================================================

        gs.error(
            'Patient Dashboard Widget Error: ' + e.message
        );

        data.error =
            'Unable to load dashboard information.';

    }

})();
